/** HTTP methods supported by Refine's `custom` data provider method. */
export type Method = "get" | "post" | "put" | "patch" | "delete";

/** Shape of the request types generated by `@hey-api/typescript` (`*Data`). */
export type RequestShape = {
  url: string;
  path?: unknown;
  query?: unknown;
  body?: unknown;
  headers?: unknown;
};

/** A backend operation: method + URL template, typed by its generated request/response types. */
export type Endpoint<D extends RequestShape = RequestShape, R = unknown> = {
  method: Method;
  url: D["url"];
  /** Phantom fields carrying the types. */
  readonly __request?: D;
  readonly __response?: R;
};

export function endpoint<D extends RequestShape, R>(method: Method, url: D["url"]): Endpoint<D, R> {
  return { method, url };
}

/** Request arguments of an endpoint (path / query / body / headers). */
export type Args<D extends RequestShape> = Omit<D, "url">;

/** Payload inside the `{ status, data }` envelope of a response type. */
export type Payload<R> = R extends { status: unknown; data?: infer P } ? P : R;

type AnyArgs = { path?: unknown; query?: unknown; body?: unknown; headers?: unknown };

/**
 * Fill `{param}` placeholders of a URL template from the path params, falling
 * back to a query param of the same name (a few endpoints declare `/{id}` but
 * read `id` from the query string).
 */
export function fillPath(url: string, path?: unknown, query?: unknown) {
  const from = (src: unknown, key: string) => (src as Record<string, unknown> | undefined)?.[key];
  return url.replace(/\{(\w+)\}/g, (_, key: string) => encodeURIComponent(String(from(path, key) ?? from(query, key) ?? "")));
}

/**
 * Query values as the Spring backend binds them: arrays as comma-separated
 * values (qs would send `ids[0]=1`), and no null / undefined entries.
 */
export function toSearchParams(query: unknown): Record<string, string | number | boolean> {
  const out: Record<string, string | number | boolean> = {};
  for (const [key, value] of Object.entries((query ?? {}) as Record<string, unknown>)) {
    if (value === undefined || value === null || value === "") continue;
    out[key] = Array.isArray(value) ? value.join(",") : (value as string | number | boolean);
  }
  return out;
}

export function argsOf(args?: unknown): AnyArgs {
  return (args ?? {}) as AnyArgs;
}
